 public static Button Button(string text,Action action){var b=new SoftButton{Text=text,AutoSize=true,Margin=new Padding(0,0,8,0)};b.Click+=(s,e)=>action();return b;}
 public static Image Logo(bool launch){return ResourceImage(launch?"run-turquoise.png":"editor.png");}
