  grid.DragLeave+=(s,e)=>{dropSlot=-1;grid.Invalidate();};
  grid.DragDrop+=HandleDrop;
  grid.Paint+=(s,e)=>{if(dropSlot<0||grid.RowCount==0)return;int row=Math.Min(dropSlot,grid.RowCount-1);var bounds=grid.GetRowDisplayRectangle(row,false);int y=dropSlot==grid.RowCount?bounds.Bottom-2:bounds.Top;if(y<grid.ColumnHeadersHeight||y>grid.ClientSize.Height)return;using(var pen=new Pen(Theme.Accent,3))e.Graphics.DrawLine(pen,3,y,grid.ClientSize.Width-5,y);};
 }
 bool ValidDrag(DragEventArgs e){return !busy&&!broken&&dragId!=null&&e.Data!=null&&e.Data.GetDataPresent(typeof(string))&&String.Equals(e.Data.GetData(typeof(string)) as string,dragId,StringComparison.Ordinal);}
 bool ValidFiles(DragEventArgs e){return !busy&&!broken&&config!=null&&e.Data!=null&&e.Data.GetDataPresent(DataFormats.FileDrop);}
 void AddDroppedFiles(string[] files){var batch=DropBatch.Prepare(files,config.Entries);using(var dialog=new Form{Text="Ajouter les programmes déposés",Size=new Size(690,430),StartPosition=FormStartPosition.CenterParent,Padding=new Padding(16)}){var list=new ListBox{Dock=DockStyle.Fill,HorizontalScrollbar=true};foreach(var entry in batch.Added)list.Items.Add("Ajouter : "+entry.Name+" — "+entry.Target);foreach(string issue in batch.Issues)list.Items.Add("Ignoré : "+issue);dialog.Controls.Add(list);var actions=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=50};var confirm=Theme.Button("Ajouter "+batch.Added.Count+" programme(s)",()=>dialog.DialogResult=DialogResult.OK);confirm.Enabled=batch.Added.Count>0;actions.Controls.Add(confirm);actions.Controls.Add(Theme.Button("Annuler",()=>dialog.DialogResult=DialogResult.Cancel));dialog.Controls.Add(actions);Theme.Apply(dialog);Theme.Primary(confirm);if(dialog.ShowDialog(this)==DialogResult.OK){config.Entries.AddRange(batch.Added);Save();RefreshRows();info.Text=batch.Added.Count+" programme(s) ajouté(s).";}}}
 public static bool ConfirmElevation(IWin32Window owner,Entry entry){return MessageBox.Show(owner,"La fermeture de « "+entry.Name+" » nécessite des droits administrateur.\n\nPanda Launcher va demander à Windows l’autorisation de fermer ce logiciel. La fenêtre Windows peut afficher « Éditeur inconnu », car Panda Launcher n’est pas signé.\n\nCliquez sur OK pour afficher cette demande, ou sur Annuler pour laisser le logiciel ouvert.","Autoriser la fermeture de "+entry.Name,MessageBoxButtons.OKCancel,MessageBoxIcon.Information)==DialogResult.OK;}
 public static bool ConfirmForce(IWin32Window owner,Entry entry){return MessageBox.Show(owner,"« "+entry.Name+" » est toujours actif. Forcer l'arrêt de ses processus ?\n\nLes données non enregistrées et les enregistrements en cours peuvent être perdus. Choisissez Non pour le laisser ouvert.","Fermeture forcée",MessageBoxButtons.YesNo,MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2)==DialogResult.Yes;}
 async void CloseApplications(){if(busy||broken||config==null)return;using(var gate=new LaunchLock(Launcher.LockName)){if(!gate.Acquired){MessageBox.Show(this,"Une opération est déjà en cours.");return;}busy=true;viewRevision++;launchErrors.Clear();commands.Enabled=false;groupArea.Enabled=false;bottom.Enabled=false;grid.Enabled=false;try{int errors=await AppCloser.Close(config,(entry,state,error)=>{int i=config.Entries.FindIndex(x=>x.Id==entry.Id);grid.Rows[i].Cells[3].Value=state;grid.Rows[i].Cells[3].ToolTipText=state;if(error)launchErrors[entry.Id]=state;else launchErrors.Remove(entry.Id);info.Text=entry.Name+" : "+state;},entry=>ConfirmForce(this,entry),8000,entry=>ConfirmElevation(this,entry));info.Text=errors==0?"Fermeture du launcher terminée.":"Certains logiciels restent ouverts : consultez leurs confirmations ou les états.";}catch(Exception ex){MessageBox.Show(this,ex.Message);}finally{busy=false;commands.Enabled=!broken;groupArea.Enabled=!broken;bottom.Enabled=!broken;grid.Enabled=!broken;RefreshRuntimeAsync();}}}
 int SlotAt(Point p){for(int i=0;i<grid.RowCount;i++){var r=grid.GetRowDisplayRectangle(i,false);if(r.Height<=0)continue;if(p.Y<r.Top+r.Height/2)return i;}return grid.RowCount;}
 void HandleDrop(object sender,DragEventArgs e){if(ValidFiles(e)){AddDroppedFiles((string[])e.Data.GetData(DataFormats.FileDrop));return;}if(!ValidDrag(e))return;int slot=SlotAt(grid.PointToClient(new Point(e.X,e.Y)));int moved=Entries.MoveToSlot(config,dragId,slot);dropSlot=-1;if(moved<0)return;Save();RefreshRows();grid.ClearSelection();grid.Rows[moved].Selected=true;grid.CurrentCell=grid.Rows[moved].Cells[1];info.Text="Ordre de lancement enregistré.";}
 void MoveEntry(int direction){int i=Selected(),j=i+direction;if(i<0||j<0||j>=config.Entries.Count)return;var e=config.Entries[i];config.Entries.RemoveAt(i);config.Entries.Insert(j,e);Save();RefreshRows();grid.ClearSelection();grid.Rows[j].Selected=true;}
 async void Launch(){using(var gate=new LaunchLock(Launcher.LockName)){if(!gate.Acquired){MessageBox.Show(this,"Une séquence de lancement est déjà en cours.");return;}busy=true;launchErrors.Clear();commands.Enabled=false;groupArea.Enabled=false;bottom.Enabled=false;grid.Enabled=false;launchButton.Text="Lancement en cours…";try{catalog=store.Read();config=catalog.Selected;if(!File.Exists(store.PathName))store.Save(catalog);RefreshGroups();RefreshRows();int n=await Launcher.Run(config,(entry,state,error)=>{int i=config.Entries.FindIndex(x=>x.Id==entry.Id);if(error)launchErrors[entry.Id]=state;else launchErrors.Remove(entry.Id);grid.Rows[i].Cells[3].Value=state;grid.Rows[i].Cells[3].Style.ForeColor=error?Color.FromArgb(182,48,65):Color.FromArgb(25,123,91);grid.Rows[i].Cells[3].ToolTipText=state;info.Text=entry.Name+" : "+state;});info.Text=n==0?"Séquence terminée. Demandes envoyées à Windows ; la disponibilité des logiciels n’est pas vérifiée.":n+" erreur(s). Survolez les états pour lire le détail.";}catch(Exception ex){MessageBox.Show(this,ex.Message);}finally{busy=false;commands.Enabled=!broken;groupArea.Enabled=!broken;bottom.Enabled=!broken;grid.Enabled=!broken;launchButton.Text="Lancer mes logiciels  →";RefreshRuntimeAsync();}}}
}
public class ProgressForm : Form {
 ListBox messages=new ListBox{Dock=DockStyle.Fill,HorizontalScrollbar=true};bool busy=true;Button edit;bool closing;string groupId;PictureBox logo;Label title;
 public ProgressForm(string requestedGroup=null,bool close=false){closing=close;groupId=requestedGroup;Text="Panda Launcher";Size=new Size(740,390);Padding=new Padding(22);StartPosition=FormStartPosition.CenterScreen;Controls.Add(messages);var header=new Panel{Dock=DockStyle.Top,Height=100};logo=new PictureBox{Image=Theme.Logo(true),SizeMode=PictureBoxSizeMode.Zoom,Size=new Size(90,90),Dock=DockStyle.Left};header.Controls.Add(logo);title=new Label{Text=closing?"Fermeture du launcher":"Lancement du launcher",AutoSize=true,Location=new Point(104,24)};header.Controls.Add(title);Controls.Add(header);edit=Theme.Button("Ouvrir la configuration",()=>{System.Diagnostics.Process.Start(Application.ExecutablePath,groupId==null?"":"--group "+groupId);Close();});edit.Dock=DockStyle.Bottom;edit.Height=45;edit.Visible=false;Controls.Add(edit);Theme.Apply(this);title.Font=new Font("Segoe UI Semibold",19);messages.BorderStyle=BorderStyle.None;messages.ItemHeight=28;messages.BackColor=Theme.Surface;Theme.Primary(edit);Shown+=(s,e)=>Run();FormClosing+=(s,e)=>{if(busy)e.Cancel=true;};}
 async void Run(){using(var gate=new LaunchLock(Launcher.LockName)){if(!gate.Acquired){busy=false;MessageBox.Show(this,"Une séquence de lancement est déjà en cours.");Close();return;}int errors=0;try{var store=new CatalogStore();var catalog=store.Read();if(!File.Exists(store.PathName))store.Save(catalog);var c=catalog.ForLaunch(groupId);groupId=c.Id;title.Text=c.Name;Text="Panda Launcher — "+c.Name;logo.Image=Theme.RunLogo(c.Icon);if(closing)errors=await AppCloser.Close(c,(e,state,err)=>messages.Items.Add(e.Name+" — "+state),e=>MainForm.ConfirmForce(this,e),8000,e=>MainForm.ConfirmElevation(this,e));else if(!c.Entries.Any(x=>x.Enabled)){messages.Items.Add("Aucun logiciel activé dans ce launcher. Ouvrez la configuration.");errors++;}else errors=await Launcher.Run(c,(e,state,err)=>messages.Items.Add(e.Name+" — "+state));}catch(Exception ex){errors++;messages.Items.Add(ex.Message);Journal.Write(ex.Message);}busy=false;if(errors==0)Close();else edit.Visible=true;}}
}
public static class Program {
 public static string GroupArgument(string[] args){if(args.Count(x=>x=="--group")>1||args.Contains("--launch")&&args.Contains("--close"))throw new IOException("Arguments de raccourci contradictoires.");int index=Array.IndexOf(args,"--group");if(index<0)return null;Guid id;if(index+1>=args.Length||!Guid.TryParseExact(args[index+1],"D",out id))throw new IOException("Identifiant de launcher invalide dans le raccourci.");return id.ToString("D");}
 [STAThread] public static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{if(args.Length>0&&args[0]=="--process-action"){try{if(args.Length!=5||(args[3]!="force"&&args[3]!="close"))throw new IOException("Action invalide.");bool acted=AppCloser.ActOnProcess(int.Parse(args[1]),long.Parse(args[2]),System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(args[4])),args[3]=="force");Environment.ExitCode=acted?0:1;}catch{Environment.ExitCode=1;}return;}string group=GroupArgument(args);Application.Run(args.Contains("--launch")||args.Contains("--close")?(Form)new ProgressForm(group,args.Contains("--close")):new MainForm(null,group));}catch(Exception ex){MessageBox.Show(ex.Message,"Panda Launcher",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
}
